const body = ($('Recibir reporte').first().json.body) || {};
const mes = String(body.mes || '').trim();
const tipo = String(body.tipo || 'general').trim().toLowerCase();
const usuarioId = Number(body.usuario_id || 0);

const valido = /^\d{4}-(0[1-9]|1[0-2])$/.test(mes) && mes >= '2020-01' && mes <= '2100-12'
  && ['general', 'doctores', 'secretarias'].includes(tipo)
  && Number.isInteger(usuarioId) && usuarioId >= 0;

return [{ json: { valido, mes, tipo, usuario_id: usuarioId } }];
